// src/components/MainPage.js
import React from 'react';
import styled from 'styled-components';

const MainContainer = styled.div`
  text-align: center;
  padding: 40px;
`;

const HeroSection = styled.div`
  background-color: #f4f4f9;
  padding: 60px 20px;
  margin-bottom: 40px;
`;

const HeroTitle = styled.h1`
  font-size: 3rem;
  color: #264653;
  margin-bottom: 20px;
`;

const HeroSubtitle = styled.p`
  font-size: 1.2rem;
  color: #2a9d8f;
`;

const FeatureList = styled.ul`
  list-style: none;
  padding: 0;
  display: flex;
  justify-content: center;
  gap: 50px;
`;

const FeatureItem = styled.li`
  font-size: 1.2rem;
  color: #1d3557;
`;

const MainPage = () => {
  return (
    <MainContainer>
      <HeroSection>
        <HeroTitle>Welcome to TriGear</HeroTitle>
        <HeroSubtitle>Your guide to the best triathlon gear</HeroSubtitle>
      </HeroSection>

      <h2>Why Choose Us?</h2>
      <FeatureList>
        <FeatureItem>✔️ Comprehensive Gear Reviews</FeatureItem>
        <FeatureItem>✔️ Expert Advice for Beginners</FeatureItem>
        <FeatureItem>✔️ Curated Product Lists</FeatureItem>
      </FeatureList>
    </MainContainer>
  );
};

export default MainPage;
